package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RequireEmailVerificationVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property require email verification of tenant config ")
  void test_require_email_verification_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> RequireEmailVerificationVO.tryFrom(null));
    Assertions.assertEquals(true,
        RequireEmailVerificationVO.from(true).isRequireEmailVerification());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RequireEmailVerificationVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", RequireEmailVerificationVO.from(true).toString());
  }
}
